// Classification Policy helper
// Reads the DataHub info the manager sends and gives a verdict.

const input = $input.first().json;

// The manager will send us the datahub_context object.
const dh = input.datahub_context || input;

const classification = (dh.classification || 'UNKNOWN').toUpperCase();
const dataset = dh.dataset || 'unknown dataset';

let verdict = 'approve';
let reason = '';

if (classification === 'PII') {
  verdict = 'deny';
  reason = "Classification Policy: '" + dataset + "' is PII (personal data) — blocked.";
} else if (classification === 'CONFIDENTIAL') {
  verdict = 'human_review';
  reason = "Classification Policy: '" + dataset + "' is Confidential — needs a human to review.";
} else if (classification === 'INTERNAL') {
  verdict = 'approve';
  reason = "Classification Policy: '" + dataset + "' is Internal — allowed.";
} else if (classification === 'PUBLIC') {
  verdict = 'approve';
  reason = "Classification Policy: '" + dataset + "' is Public — allowed.";
} else {
  verdict = 'human_review';
  reason = "Classification Policy: classification is UNKNOWN — needs a human to review.";
}

return { json: { policy: 'classification', verdict, reason } };
